import data from "./leanings.json" with { type: "json" };
import type { LeaningName } from "./rubric.js";

/**
 * Ideological leanings, built from Armando's Notion doc "Leanings" (src/framework/leanings.json,
 * generated by scripts/import-leanings.mts). Two kinds, both of Geo type Ideology:
 * - traditions: classic ideologies such as Conservative or Socialist;
 * - issue leanings: one side of a political issue, such as Pro-life or Pro-gun control.
 * A claim can carry several ideological leanings but at most one political leaning.
 */

export interface Tenet {
  id: string;
  text: string;
  /** True when this position belongs to this leaning alone. */
  distinctive: boolean;
}

export interface IdeologyCard {
  name: string;
  /** Geo value ID, or null while the value is not on Geo yet (it can never go into a proposal then). */
  geoId: string | null;
  kind: "tradition" | "issue";
  /** Armando's description. */
  definition: string;
  /** For issue leanings: the issue, e.g. "Abortion". */
  issue: string | null;
  group: string;
  aliases: string[];
  source: string;
  status: "Draft" | "Approved";
  /** Traditions: positions characteristic of the tradition. Issue leanings: the side itself. */
  tenets: Tenet[];
  exclusions: string[];
  /** Traditions: related traditions. Issue leanings: the other side(s) of the issue. */
  neighbours: string[];
  /** Leanings a tradition is usually found at; a tradition outside them is not published. */
  typicalLeanings: LeaningName[];
  /** The example claim Armando linked to this leaning, if any. */
  exampleClaimId: string | null;
}

interface LeaningRow {
  name: string;
  kind: string;
  description: string;
  issue: string | null;
  group: string;
  alternativeNames: string[];
  slogan: string | null;
  exampleClaimId: string | null;
  geoId: string | null;
  otherSides: string[];
}

const ALL: LeaningName[] = ["Far left", "Left", "Center left", "Center", "Center right", "Right", "Far right"];
const ARMANDO = "Armando's Notion doc \"Leanings\" (2026-10-23)";

interface TraditionDetail {
  /** Positions adherents typically hold; matching one is enough (Armando's convention). */
  positions: string[];
  exclusions: string[];
  neighbours: string[];
  typical: LeaningName[];
}

