function toCard(row: LeaningRow): IdeologyCard {
  const base = {
    name: row.name,
    geoId: row.geoId,
    definition: row.description,
    group: row.group,
    aliases: [...row.alternativeNames, ...(row.slogan ? [`"${row.slogan}"`] : [])],
    source: ARMANDO,
    status: "Draft" as const,
    exampleClaimId: row.exampleClaimId,
  };
  if (row.kind === "issue") {
    return {
      ...base,
      kind: "issue",
      issue: row.issue,
      tenets: [{ id: "T1", text: row.description, distinctive: true }],
      exclusions: [
        `The claim takes the other side of ${row.issue} (${row.otherSides.join(" or ")}).`,
        `The claim only mentions ${row.issue} without taking a side, or reports someone else's side.`,
      ],
      neighbours: row.otherSides,
      typicalLeanings: ALL,
    };
  }
  const detail = TRADITIONS[row.name];
  if (!detail) throw new Error(`No characteristic positions written for the tradition "${row.name}"`);
  return {
    ...base,
    kind: "tradition",
    issue: null,
    tenets: detail.positions.map((text, i) => ({ id: `T${i + 1}`, text, distinctive: false })),
    exclusions: detail.exclusions,
    neighbours: detail.neighbours,
    typicalLeanings: detail.typical,
  };
}

export const IDEOLOGY_CARDS: IdeologyCard[] = (data.ideologies as LeaningRow[]).map(toCard);

export const CARD_BY_NAME: ReadonlyMap<string, IdeologyCard> = new Map(IDEOLOGY_CARDS.map((c) => [c.name, c]));

/** Issues in the order Armando listed them, each with its sides. */
export const ISSUES: { issue: string; group: string; sides: IdeologyCard[] }[] = [
  ...new Map(IDEOLOGY_CARDS.filter((c) => c.kind === "issue").map((c) => [c.issue!, c.group])).entries(),
].map(([issue, group]) => ({ issue, group, sides: IDEOLOGY_CARDS.filter((c) => c.issue === issue) }));

/** Armando's Political leanings table: the 7 spectrum values plus Nonpartisan, with alternative names. */
export const POLITICAL_LEANING_VALUES = data.politicalLeanings;
